<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>LUSTRE — Detailing Atelier</title>

    <!-- Three.js CDN -->
    <script src="https://cdn.jsdelivr.net/npm/three@0.159.0/build/three.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.159.0/examples/js/controls/OrbitControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.159.0/examples/js/loaders/GLTFLoader.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.159.0/examples/js/libs/draco/draco_decoder.min.js"></script>

    <!-- GSAP for scroll animations -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.4/gsap.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.4/ScrollTrigger.min.js"></script>

    <!-- Lenis for smooth scrolling -->
    <link href="https://cdn.jsdelivr.net/npm/@studio-freight/lenis@1.0.42/dist/lenis.min.css" rel="stylesheet">
    <script src="https://cdn.jsdelivr.net/npm/@studio-freight/lenis@1.0.42/dist/lenis.js"></script>

    <!-- Fonts -->
    <link href="https://fonts.googleapis.com/css2?family=Manrope:wght@300;400;500;600;700&family=Syncopate:wght@400;500;600;700&display=swap" rel="stylesheet">

    <style>
        /* ========================
           ROOT VARIABLES
           ======================== */
        :root {
            --bg-charcoal: #121212;
            --bg-dark: #1A1A1A;
            --bg-mid: #252525;
            --bg-light: #2F2F2F;

            --text-ivory: #E8E6E4;
            --text-warm-ivory: #EFECE7;
            --text-dim: #9A9A9A;

            --accent-gold: #C8B890;
            --accent-blue: #5FA2D1;

            --font-main: 'Manrope', -apple-system, sans-serif;
            --font-display: 'Syncopate', -apple-system, sans-serif;

            --border-light: rgba(232, 230, 228, 0.15);
            --shadow-soft: rgba(0, 0, 0, 0.4);

            --ease-smooth: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-fast: 200ms;
            --duration-normal: 400ms;
            --duration-slow: 800ms;
        }

        /* ========================
           BASE RESET & TYPOGRAPHY
           ======================== */
        *, *::before, *::after {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        html.lenis {
            height: auto;
        }

        html.lenis body {
            overscroll-behavior: auto;
        }

        .lenis.lenis-smooth {
            scroll-padding-top: 0px !important;
            scroll-snap-type: y proximity;
        }

        .lenis.lenis-smooth [data-lenis-prevent] {
            overscroll-behavior: contain;
        }

        .lenis.lenis-stopped {
            overflow: hidden;
        }

        body {
            font-family: var(--font-main);
            background-color: var(--bg-charcoal);
            color: var(--text-ivory);
            line-height: 1.6;
            overflow-x: hidden;
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
        }

        h1, h2, h3, h4 {
            font-family: var(--font-display);
            text-transform: uppercase;
            line-height: 1.15;
            letter-spacing: -0.02em;
        }

        p {
            color: var(--text-dim);
            font-size: 1rem;
        }

        .container {
            width: 90%;
            max-width: 1800px;
            margin: 0 auto;
        }

        /* ========================
           SECTION: NAVIGATION
           ======================== */
        .nav-wrapper {
            position: fixed;
            top: 24px;
            left: 50%;
            transform: translateX(-50%);
            z-index: 100;
            background: rgba(26, 26, 26, 0.85);
            backdrop-filter: blur(8px);
            padding: 12px 32px;
            border-radius: 48px;
            border: 1px solid var(--border-light);
            transition: all 0.3s var(--ease-smooth);
        }

        .nav-wrapper:hover {
            background: rgba(37, 37, 37, 0.95);
            border-color: rgba(232, 230, 228, 0.25);
        }

        .nav-list {
            display: flex;
            gap: 40px;
            list-style: none;
        }

        .nav-link {
            font-family: var(--font-display);
            font-size: 0.78rem;
            color: var(--text-ivory);
            text-decoration: none;
            letter-spacing: 0.1em;
            position: relative;
            transition: color 0.2s ease;
        }

        .nav-link::after {
            content: '';
            position: absolute;
            bottom: -4px;
            left: 50%;
            transform: translateX(-50%);
            width: 6px;
            height: 1px;
            background-color: var(--accent-gold);
            transition: all 0.2s ease;
        }

        .nav-link:hover {
            color: var(--text-warm-ivory);
        }

        .nav-link:hover::after,
        .nav-link.active::after {
            width: 16px;
        }

        /* ========================
           SECTION: HERO (3D CAR + LUSTRE)
           ======================== */
        #hero {
            position: relative;
            height: 140vh;
            overflow: hidden;
        }

        .hero-scene-container {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
        }

        #canvas-container {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
        }

        .hero-overlay {
            position: absolute;
            bottom: -12vh;
            left: 50%;
            transform: translateX(-50%);
            z-index: 10;
            text-align: center;
        }

        .hero-wordmark {
            font-family: var(--font-display);
            font-size: clamp(7rem, 15vw, 28rem);
            line-height: 0.9;
            letter-spacing: -0.05em;
            color: rgba(232, 230, 228, 0.04);
            mix-blend-mode: overlay;
            pointer-events: none;
        }

        .hero-content {
            position: absolute;
            top: 50%;
            left: 12%;
            transform: translateY(-50%);
            z-index: 20;
            max-width: 480px;
        }

        .hero-title {
            font-size: clamp(3rem, 6vw, 4.5rem);
            color: var(--text-ivory);
            margin-bottom: 16px;
        }

        .hero-subtitle {
            font-size: 1.08rem;
            max-width: 28rem;
            margin-bottom: 32px;
        }

        .hero-btn-group {
            display: flex;
            gap: 16px;
            flex-wrap: wrap;
        }

        /* ========================
           SECTION: PAINT CORRECTION
           ======================== */
        #paint-correction {
            position: relative;
            padding-top: 240px;
            min-height: 85vh;
        }

        .section-header {
            display: flex;
            gap: 32px;
            margin-bottom: 64px;
            align-items: center;
        }

        .section-number {
            font-family: var(--font-display);
            color: var(--accent-gold);
            font-size: 5.5rem;
            line-height: 1;
            opacity: 0.8;
        }

        .section-title {
            font-size: clamp(2rem, 4vw, 3rem);
            color: var(--text-ivory);
            max-width: 65ch;
        }

        #paint-correction-content {
            display: grid;
            grid-template-columns: 1fr 1.2fr;
            gap: 80px;
            align-items: center;
        }

        .content-text {
            padding-right: 64px;
        }

        .content-text h3 {
            font-size: clamp(1.5rem, 3vw, 2rem);
            margin-bottom: 20px;
        }

        .tech-label {
            display: inline-block;
            background: var(--bg-light);
            color: var(--text-dim);
            font-size: 0.75rem;
            padding: 6px 12px;
            border-radius: 4px;
            margin-bottom: 16px;
            letter-spacing: 0.1em;
        }

        .section-image {
            position: relative;
        }

        .section-image img,
        .section-image .scene-fallback {
            width: 100%;
            border-radius: 8px;
        }

        .section-image::after {
            content: '';
            position: absolute;
            top: -32px;
            right: -32px;
            width: 240px;
            height: 100%;
            background: linear-gradient(
                135deg,
                rgba(95, 162, 209, 0.15) 0%,
                transparent 50%
            );
            border-radius: 8px;
        }

        /* ========================
           SECTION: CERAMIC COATING
           ======================== */
        #ceramic-coating {
            position: relative;
            padding-top: 240px;
            min-height: 85vh;
        }

        .coating-grid {
            display: grid;
            grid-template-columns: 1.3fr 1fr;
            gap: 64px;
        }

        #ceramic-coating-content {
            padding-left: 0;
        }

        /* ========================
           SECTION: PROTECTION FILM
           ======================== */
        #protection-film {
            position: relative;
            padding-top: 240px;
            min-height: 85vh;
        }

        .pf-wrapper {
            display: grid;
            grid-template-columns: 1fr 1.3fr;
            gap: 64px;
            align-items: center;
        }

        #protection-film-content {
            padding-right: 0;
        }

        /* ========================
           SECTION: COLOUR CHANGE
           ======================== */
        #colour-change {
            position: relative;
            padding-top: 240px;
            min-height: 85vh;
        }

        .cc-wrapper {
            display: grid;
            grid-template-columns: 1fr 1.3fr;
            gap: 64px;
        }

        #colour-change-content {
            padding-left: 0;
        }

        /* ========================
           SECTION: SERVICE PACKAGES
           ======================== */
        #services {
            position: relative;
            padding-top: 240px;
            min-height: auto;
        }

        .packages-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 28px;
            margin-bottom: 64px;
        }

        .package-card {
            background: var(--bg-dark);
            border: 1px solid var(--border-light);
            padding: 40px 32px;
            border-radius: 8px;
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .package-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 12px 32px var(--shadow-soft);
            border-color: rgba(95, 162, 209, 0.25);
        }

        .package-name {
            font-family: var(--font-display);
            font-size: 1.1rem;
            margin-bottom: 8px;
        }

        .package-price {
            font-family: var(--font-display);
            color: var(--accent-gold);
            font-size: 1.4rem;
            margin-bottom: 20px;
        }

        .package-features {
            display: flex;
            flex-direction: column;
            gap: 6px;
            font-size: 0.88rem;
        }

        /* ========================
           SECTION: PRICING
           ======================== */
        #pricing {
            position: relative;
            padding-top: 240px;
            min-height: auto;
        }

        .pricing-table-wrap {
            background: var(--bg-dark);
            border: 1px solid var(--border-light);
            border-radius: 8px;
            overflow: hidden;
            margin-top: 64px;
        }

        .pricing-row {
            display: grid;
            grid-template-columns: 3fr 2.5fr;
            padding: 20px 32px;
            border-bottom: 1px solid var(--border-light);
            font-size: 0.9rem;
        }

        .pricing-row:last-child {
            border-bottom: none;
        }

        /* ========================
           SECTION: APPOINTMENTS & CONTACT
           ======================== */
        #appointments {
            position: relative;
            padding-top: 240px;
            min-height: auto;
        }

        .appointment-wrapper {
            display: grid;
            grid-template-columns: 1fr 1.5fr;
            gap: 64px;
            align-items: start;
        }

        #appointments-content {
            padding-left: 0;
        }

        .form-container {
            background: var(--bg-dark);
            border: 1px solid var(--border-light);
            padding: 56px;
            border-radius: 8px;
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-label {
            display: block;
            font-size: 0.8rem;
            text-transform: uppercase;
            letter-spacing: 0.1em;
            color: var(--text-dim);
            margin-bottom: 8px;
        }

        .form-input, .form-select {
            width: 100%;
            background: var(--bg-mid);
            border: 1px solid var(--border-light);
            padding: 16px 20px;
            font-family: var(--font-main);
            color: var(--text-ivory);
            font-size: 1rem;
            border-radius: 4px;
            transition: all 0.2s ease;
        }

        .form-input:focus, .form-select:focus {
            outline: none;
            border-color: var(--accent-blue);
            background: var(--bg-light);
        }

        /* ========================
           SECTION: FOOTER
           ======================== */
        footer {
            position: relative;
            padding-top: 240px;
            min-height: 65vh;
        }

        .footer-wrapper {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 80px;
            align-items: start;
        }

        #footer-content {
            padding-right: 0;
        }

        .footer-headline {
            font-size: clamp(2.5rem, 6vw, 3.5rem);
            margin-bottom: 24px;
            line-height: 1.15;
        }

        .footer-text {
            max-width: 480px;
            margin-bottom: 48px;
        }

        .footer-cta-btn {
            display: inline-block;
            font-family: var(--font-display);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            color: var(--text-ivory);
            background: transparent;
            padding: 16px 28px;
            border-radius: 4px;
            transition: all 0.2s ease;
        }

        .footer-cta-btn:hover {
            background: rgba(95, 162, 209, 0.15);
        }

        /* ========================
           LOADING & FALLBACKS
           ======================== */
        #loading-screen {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: var(--bg-charcoal);
            z-index: 1000;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .loader {
            position: relative;
            width: 120px;
            height: 120px;
        }

        .loader::before,
        .loader::after {
            content: '';
            position: absolute;
            border-radius: 50%;
        }

        .loader::before {
            width: 100%;
            height: 100%;
            top: -14px;
            left: -14px;
            background: conic-gradient(from 0deg, var(--accent-gold) 50%, transparent 0);
            animation: rotate 1.8s linear infinite;
        }

        .loader::after {
            width: 76%;
            height: 76%;
            top: -24px;
            left: -34px;
            background-color: var(--bg-dark);
        }

        @keyframes rotate {
            to {
                transform: rotate(1turn);
            }
        }

        /* ========================
           RESPONSIVE & ACCESSIBILITY
           ======================== */
        .sr-only {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: -1px;
            overflow: hidden;
            clip: rect(0, 0, 0, 0);
            white-space: nowrap;
        }

        @media (max-width: 1200px) {
            .packages-grid,
            #paint-correction-content,
            #ceramic-coating,
            #protection-film,
            #colour-change,
            .cc-wrapper,
            #footer-wrapper,
            #appointment-wrapper {
                grid-template-columns: 1fr;
                gap: 48px;
            }

            #paint-correction-content > div:last-child,
            #ceramic-coating-content,
            #protection-film-content,
            #colour-change-content,
            .cc-wrapper {
                padding-left: 0 !important;
                padding-right: 0 !important;
            }

            .coating-grid > div:last-child,
            .pf-wrapper > div:first-child,
            #appointment-wrapper > div:first-child,
            .footer-wrapper {
                order: 1;
            }

            #paint-correction-content > div:last-child,
            #ceramic-coating-content,
            #protection-film-content,
            #colour-change-content,
            .coating-grid,
            .pf-wrapper,
            .cc-wrapper,
            #appointment-wrapper,
            .footer-wrapper {
                order: 2;
            }

            #paint-correction-content > div:first-child:last-of-type,
            #ceramic-coating-content,
            #protection-film-content,
            #colour-change-content,
            #appointment-wrapper > div:first-child,
            .coating-grid > div:first-child:last-of-type,
            .pf-wrapper > div:first-child,
            .cc-wrapper {
                order: 2;
            }

            .packages-grid {
                grid-template-columns: 1fr;
            }
        }

        @media (max-width: 768px) {
            .hero-wordmark {
                font-size: clamp(5rem, 12vw, 20rem);
            }

            .nav-wrapper {
                padding: 12px 24px;
            }

            .section-number {
                font-size: 3.5rem;
            }

            #canvas-container {
                width: auto !important;
                height: auto !important;
                position: relative;
            }
        }

        @media (max-width: 480px) {
            .hero-content,
            #paint-correction-content,
            #ceramic-coating,
            #protection-film,
            #colour-change,
            #appointment-wrapper,
            .footer-wrapper,
            .packages-grid {
                padding: 16px;
                gap: 32px;
            }

            .hero-title {
                font-size: clamp(2rem, 5vw, 3.2rem);
            }
        }

        /* ========================
           REDUCED MOTION & FOCUS
           ======================== */
        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                animation-iteration-count: 1 !important;
                transition-duration: 0.01ms !important;
                scroll-behavior: auto !important;
            }

            .loader::before,
            .loader::after {
                animation-duration: 3s !important;
            }
        }

        :focus-visible {
            outline: 2px solid var(--accent-gold);
            outline-offset: -4px;
        }

        /* ========================
           SCROLL PROGRESS BAR
           ======================== */
        .scroll-progress-container {
            position: fixed;
            right: 32px;
            top: 50%;
            transform: translateY(-50%);
            z-index: 90;
            display: flex;
            gap: 48px;
        }

        .progress-line {
            position: absolute;
            left: 16px;
            top: -24px;
            bottom: -24px;
            width: 3px;
            background: rgba(232, 230, 228, 0.2);
        }

        .progress-fill {
            position: absolute;
            left: 16px;
            top: 0;
            bottom: 0;
            width: 3px;
            background: var(--accent-gold);
            border-radius: 2px;
            transition: height 0.4s ease, bottom 0.4s ease;
        }

        /* ========================
           THREE.JS SCENE STYLES
           ======================== */
        .scene-wrapper {
            position: absolute;
            top: 50%;
            left: 50%;
            width: auto;
            height: auto;
            transform-style: preserve-3d;
            pointer-events: none;
        }

        #hero-scene {
            width: 140vw;
            height: 80vh;
        }

        /* ========================
           UTILITY CLASSES
           ======================== */
        .fade-in-up {
            opacity: 0;
            transform: translateY(32px);
            transition: all 0.6s var(--ease-smooth);
        }

        .fade-in-up.visible {
            opacity: 1;
            transform: translateY(0);
        }

        /* ========================
           INSPECTION CTA BUTTONS
           ======================== */
        .hero-btn-group .btn-primary,
        .hero-btn-group .btn-secondary {
            padding: 16px 28px;
            font-family: var(--font-display);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            border-radius: 4px;
            transition: all 0.2s ease;
            cursor: pointer;
        }

        .btn-primary {
            background: var(--text-warm-ivory);
            color: var(--bg-charcoal);
            font-weight: 500;
        }

        .btn-secondary {
            background: transparent;
            border: 1px solid var(--border-light);
            color: var(--text-ivory);
        }

        .hero-btn-group .btn-primary:hover,
        .hero-btn-group .btn-secondary:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
        }

        /* ========================
           SWATCH SELECTORS (COLLOUR CHANGE)
           ======================== */
        .swatch-group {
            display: flex;
            gap: 16px;
            margin-top: 24px;
            flex-wrap: wrap;
        }

        .color-swatch {
            width: 56px;
            height: 56px;
            border-radius: 8px;
            cursor: pointer;
            transition: transform 0.2s ease, box-shadow 0.2s ease;
            position: relative;
        }

        .color-swatch:hover {
            transform: scale(1.05);
        }

        .color-swatch::after {
            content: '';
            position: absolute;
            bottom: -24px;
            left: 50%;
            transform: translateX(-50%);
            font-size: 0.7rem;
            color: var(--text-dim);
            letter-spacing: 0.1em;
        }

        /* ========================
           DYNAMIC BACKGROUND GRADIENTS
           ======================== */
        .section-accent {
            position: absolute;
            top: -5%;
            right: -8%;
            width: 42vh;
            height: 60vw;
            background: radial-gradient(ellipse, rgba(95, 162, 209, 0.1) 0%, transparent 70%);
            pointer-events: none;
        }

        .section-accent-2 {
            position: absolute;
            top: -8%;
            left: -4%;
            width: 36vw;
            height: 58vh;
            background: radial-gradient(ellipse, rgba(195, 167, 107, 0.08) 0%, transparent 70%);
            pointer-events: none;
        }

    </style>
</head>
