    <!-- ========================
         SCROLL PROGRESS INDICATOR
         ======================== -->
    <div class="scroll-progress-container" aria-hidden="true">
        <span class="progress-line"></span>
        <span class="progress-fill"></span>
    </div>

    <!-- ========================
         LOADING SCREEN
         ======================== -->
    <div id="loading-screen" role="dialog" aria-label="Loading site assets">
        <div class="loader"></div>
    </div>

    <!-- ========================
         NAVIGATION (FIXED)
         ======================== -->
    <nav class="nav-wrapper" data-lenis-prevent="true">
        <ul class="nav-list">
            <li><a href="#hero" class="nav-link active" aria-label="Hero section">Home</a></li>
            <li><a href="#paint-correction" class="nav-link" aria-label="Paint Correction">Correction</a></li>
            <li><a href="#ceramic-coating" class="nav-link" aria-label="Ceramic Coating">Coating</a></li>
            <li><a href="#protection-film" class="nav-link" aria-label="Protection Film">Film</a></li>
            <li><a href="#colour-change" class="nav-link" aria-label="Colour Change">Colour</a></li>
            <li><a href="#services" class="nav-link" aria-label="Services">Packages</a></li>
            <li><a href="#pricing" class="nav-link" aria-label="Pricing">Pricing</a></li>
            <li><a href="#appointments" class="nav-link" aria-label="Book Appointment">Inspect</a></li>
        </ul>
    </nav>

    <!-- ========================
         SECTION: HERO (3D CAR + LUSTRE)
         ======================== -->
    <section id="hero" data-section-id="hero">
        <div class="container hero-overlay">
            <h1 class="hero-wordmark">LUSTRE</h1>
        </div>

        <!-- Three.js Scene Container -->
        <div id="canvas-container" aria-hidden="true"></div>

        <!-- Hero Text Content -->
        <div class="container hero-content fade-in-up visible">
